// App Parceiros Web Push. The service worker generated by vite-plugin-pwa
// imports this file (workbox.importScripts in vite.config.ts).
// The message comes from the backend worker: { title, body, url, id }.

self.addEventListener("push", (event) => {
  let msg = {};
  try {
    msg = event.data ? event.data.json() : {};
  } catch {
    msg = { title: event.data ? event.data.text() : "" };
  }
  const title = msg.title || "App Parceiros";
  event.waitUntil(
    self.registration.showNotification(title, {
      body: msg.body || "",
      icon: "/icon.svg",
      badge: "/icon.svg",
      tag: msg.id || undefined,
      lang: "pt-BR",
      data: { url: msg.url || "/" },
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const path = (event.notification.data && event.notification.data.url) || "/";
  // Only paths inside the app.
  const target = new URL(path.startsWith("/") ? path : "/", self.location.origin).href;
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((windows) => {
      for (const w of windows) {
        if (new URL(w.url).origin === self.location.origin && "focus" in w) {
          return w.focus().then((f) => (f && "navigate" in f ? f.navigate(target) : f));
        }
      }
      return self.clients.openWindow(target);
    }),
  );
});
